def satir_farki(a, b):
    # LCS Tablosu Oluşturma
    lp = [[0] * (len(b) + 1) for _ in range(len(a) + 1)]

    for i in range(1, len(a) + 1):
        for j in range(1, len(b) + 1):
            if a[i-1] == b[j-1]:
                lp[i][j] = lp[i-1][j-1] + 1

    # Geriye doğru iz sürüp değişiklikleri belirle
    result = []
    di, dj = len(a), len(b)
    while di > 0 or dj > 0:
        if di > 0 and dj > 0 and a[di-1] == b[dj-1]:
            result.append((" ", a[di-1]))
            di -= 1
            dj -= 1
        elif dj > 0 or (di > 0 and lp[di][dj] == lp[di-1][dj]):
            # Silme: bir sonraki hücreden gelirse silgi, değilse ekle
            if di > 0 and lp[di][dj] == lp[di-1][dj]:
                result.append(("-", a[di-1]))
                di -= 1
            else:
                result.append(("+", b[dj-1]))
                dj -= 1

    return result[::-1]  # Sıralamayı düzelt ve döndür
```

